                    write_diag_text(f, k)?;
                    write!(f, ": {v}")?;
                }
                write!(f, "}}")
            }
            Self::Bool(true) => write!(f, "true"),
            Self::Bool(false) => write!(f, "false"),
            Self::Null => write!(f, "null"),
        }
    }
}

fn write_diag_text(f: &mut fmt::Formatter<'_>, s: &str) -> fmt::Result {
    write!(f, "\"")?;
    for c in s.chars() {
        match c {
            '"' => write!(f, "\\\"")?,
