165	    #[test]
166	    fn collision_between_known_and_unknown_rejects() {
167	        let original = encode(&Value::Map(sample_map()));
168	        let (mut known, unknown) =
169	            decode_map_partial(&original, known_key_set(&["v", "id"])).unwrap();
170	        known.insert("future", Value::Unsigned(0));
171	        let err = encode_map_partial(&known, &unknown).unwrap_err();
172	        assert_eq!(err.check(), "unknown-field-collision");
173	    }
174	
175	    #[test]
176	    fn non_map_top_level_rejects() {
177	        let bytes = encode(&Value::Unsigned(1));
178	        let err = decode_map_partial(&bytes, |_| true).unwrap_err();
179	        assert_eq!(err.check(), "unexpected-type");
180	    }
