182	    #[test]
183	    fn strictness_applies_inside_unknown_values() {
184	        // {"a": <non-shortest-form 1>} — the unknown value must still reject.
185	        let bytes = [0xa1, 0x61, b'a', 0x18, 0x01];
186	        let err = decode_map_partial(&bytes, |_| false).unwrap_err();
