1	//! The strict decoder. Accepts deterministic-profile CBOR only; every other
2	//! well-formed or ill-formed input rejects fail-closed with the named check
3	//! (blueprint/core.md "Wire format": one strictness policy, everywhere).
4	
5	use super::MAX_DEPTH;
6	use super::encode::{
7	    MAJOR_ARRAY, MAJOR_BYTES, MAJOR_MAP, MAJOR_NEGATIVE, MAJOR_SIMPLE, MAJOR_TEXT, MAJOR_UNSIGNED,
8	    SIMPLE_FALSE, SIMPLE_NULL, SIMPLE_TRUE,
9	};
10	use super::value::{Map, Value, canonical_key_cmp};
11	use crate::error::{CodecError, Malformed, TrustViolation};
12	
13	/// Decode exactly one deterministic-profile item spanning the whole input.
14	pub fn decode(bytes: &[u8]) -> Result<Value, CodecError> {
15	    let mut d = Decoder::new(bytes);
16	    let value = d.read_value(0)?;
17	    d.expect_end()?;
18	    Ok(value)
19	}
20	
21	pub(super) struct Decoder<'a> {
22	    input: &'a [u8],
23	    pos: usize,
24	}
25	
26	/// A parsed head: major type, argument value, the raw additional-info bits,
27	/// and where the item started. For major 7 the additional info is a selector
28	/// (simple value or float width), not an integer argument — dispatch on `ai`.
29	pub(super) struct Head {
30	    pub major: u8,
31	    pub arg: u64,
32	    pub ai: u8,
33	    pub offset: usize,
34	}
35	
36	impl<'a> Decoder<'a> {
37	    pub(super) fn new(input: &'a [u8]) -> Self {
38	        Self { input, pos: 0 }
39	    }
40	
41	    pub(super) fn pos(&self) -> usize {
42	        self.pos
43	    }
44	
45	    pub(super) fn expect_end(&self) -> Result<(), CodecError> {
46	        if self.pos != self.input.len() {
47	            return Err(Malformed::TrailingBytes { offset: self.pos }.into());
48	        }
49	        Ok(())
50	    }
51	
52	    fn take(&mut self, n: usize) -> Result<&'a [u8], CodecError> {
53	        let start = self.pos;
54	        let end = start
55	            .checked_add(n)
56	            .filter(|&e| e <= self.input.len())
57	            .ok_or(Malformed::Truncated { offset: start })?;
58	        self.pos = end;
59	        Ok(&self.input[start..end])
60	    }
61	
62	    fn take_byte(&mut self) -> Result<u8, CodecError> {
63	        Ok(self.take(1)?[0])
64	    }
65	
66	    /// Read one head, enforcing shortest-form arguments and rejecting every
67	    /// profile-forbidden shape (tags, indefinite lengths, reserved ai).
68	    pub(super) fn read_head(&mut self) -> Result<Head, CodecError> {
69	        let offset = self.pos;
70	        let initial = self.take_byte()?;
71	        let major = initial >> 5;
72	        let ai = initial & 0x1f;
73	
74	        // Tags reject on the initial byte, before argument decoding: the
75	        // profile admits none, whatever their number's form.
76	        if major == 6 {
77	            return Err(Malformed::TagForbidden { offset }.into());
78	        }
79	
80	        let arg = match self.read_arg(ai)? {
81	            Some(arg) => arg,
82	            None => {
83	                // ai 28–30 reserved everywhere; 31 is indefinite/break,
84	                // legal in no deterministic encoding.
85	                return Err(match (major, ai) {
86	                    (MAJOR_BYTES | MAJOR_TEXT | MAJOR_ARRAY | MAJOR_MAP, 31) => {
87	                        TrustViolation::IndefiniteLength { offset }.into()
88	                    }
89	                    (MAJOR_SIMPLE, 31) => CodecError::from(Malformed::UnexpectedBreak { offset }),
90	                    _ => Malformed::ReservedAdditionalInfo { offset }.into(),
91	                });
92	            }
93	        };
94	
95	        // Shortest-form enforcement (RFC 8949 §4.2.1). Major 7's ai is a
96	        // simple-value selector, not an integer argument — handled by caller.
97	        if major != MAJOR_SIMPLE {
98	            let minimal = ai < 24
99	                || match ai {
100	                    24 => arg >= 24,
101	                    25 => arg > 0xff,
102	                    26 => arg > 0xffff,
103	                    27 => arg > 0xffff_ffff,
104	                    _ => unreachable!(),
105	                };
106	            if !minimal {
107	                return Err(match major {
108	                    MAJOR_UNSIGNED | MAJOR_NEGATIVE => {
109	                        TrustViolation::NonCanonicalUint { offset }.into()
110	                    }
111	                    _ => CodecError::from(TrustViolation::NonCanonicalLength { offset }),
112	                });
113	            }
114	        }
115	
116	        Ok(Head {
117	            major,
118	            arg,
119	            ai,
120	            offset,
121	        })
122	    }
123	
124	    /// The argument for an additional-info value; `None` for 28–31.
125	    fn read_arg(&mut self, ai: u8) -> Result<Option<u64>, CodecError> {
126	        Ok(match ai {
127	            0..=23 => Some(u64::from(ai)),
128	            24 => Some(u64::from(self.take_byte()?)),
129	            25 => Some(u64::from(u16::from_be_bytes(
130	                self.take(2)?.try_into().expect("len 2"),
131	            ))),
132	            26 => Some(u64::from(u32::from_be_bytes(
133	                self.take(4)?.try_into().expect("len 4"),
134	            ))),
135	            27 => Some(u64::from_be_bytes(self.take(8)?.try_into().expect("len 8"))),
136	            _ => None,
137	        })
138	    }
139	
140	    fn take_len(&mut self, arg: u64, offset: usize) -> Result<&'a [u8], CodecError> {
141	        let remaining = (self.input.len() - self.pos) as u64;
142	        if arg > remaining {
143	            return Err(Malformed::Truncated { offset }.into());
144	        }
145	        self.take(arg as usize)
146	    }
147	
148	    pub(super) fn read_value(&mut self, depth: usize) -> Result<Value, CodecError> {
149	        if depth >= MAX_DEPTH {
150	            return Err(Malformed::DepthExceeded { offset: self.pos }.into());
151	        }
152	        let head = self.read_head()?;
153	        match head.major {
154	            MAJOR_UNSIGNED => Ok(Value::Unsigned(head.arg)),
155	            MAJOR_NEGATIVE => Ok(Value::Negative(head.arg)),
156	            MAJOR_BYTES => Ok(Value::Bytes(self.take_len(head.arg, head.offset)?.to_vec())),
157	            MAJOR_TEXT => {
158	                let raw = self.take_len(head.arg, head.offset)?;
159	                let text = core::str::from_utf8(raw).map_err(|_| Malformed::InvalidUtf8 {
160	                    offset: head.offset,
161	                })?;
162	                Ok(Value::Text(text.to_owned()))
163	            }
164	            MAJOR_ARRAY => {
165	                let mut items = Vec::new();
166	                for _ in 0..head.arg {
167	                    items.push(self.read_value(depth + 1)?);
168	                }
169	                Ok(Value::Array(items))
170	            }
171	            MAJOR_MAP => {
172	                let mut entries: Vec<(String, Value)> = Vec::new();
173	                for _ in 0..head.arg {
174	                    let key = self.read_map_key(entries.last().map(|(k, _)| k.as_str()))?;
175	                    let value = self.read_value(depth + 1)?;
176	                    entries.push((key, value));
177	                }
178	                // Order and uniqueness were enforced entry-by-entry, so this
179	                // rebuild cannot reorder or drop anything.
180	                Ok(Value::Map(entries.into_iter().collect::<Map>()))
181	            }
182	            // Dispatch on the additional info, never the argument: ai 25–27
183	            // carry float bit patterns in `arg`, which would otherwise alias
184	            // the simple-value space (e.g. a half float 0x0014 vs `false`).
185	            MAJOR_SIMPLE => match head.ai {
186	                SIMPLE_FALSE => Ok(Value::Bool(false)),
187	                SIMPLE_TRUE => Ok(Value::Bool(true)),
188	                SIMPLE_NULL => Ok(Value::Null),
189	                25..=27 => Err(Malformed::FloatForbidden {
190	                    offset: head.offset,
191	                }
192	                .into()),
193	                _ => Err(Malformed::SimpleValueForbidden {
194	                    offset: head.offset,
195	                }
196	                .into()),
197	            },

