1	//! The KAT manifest job (blueprint/core.md "KAT regime", blueprint/testing.md
2	//! "crates/core — KATs and property tests"): merge-blocking, machine-checked.
3	//!
4	//! Fixtures are embedded with `include_str!` — never loaded from the
5	//! filesystem at runtime — so the same suite runs natively and under
6	//! wasm32-wasip1 (the residual parity surface). Vectors regenerate only
7	//! through the committed generator (`examples/kat_gen.rs`); the exact counts
8	//! and coverage lists here are the anti-vacuity backstop.
9	
10	use std::collections::BTreeSet;
11	
12	use cipherbox_core::codec::{decode, decode_map_partial, encode, encode_map_partial};
13	use cipherbox_core::error::{Malformed, TrustViolation};
14	use serde::Deserialize;
15	
16	const MANIFEST: &str = include_str!("../kat/manifest.json");
17	
18	/// Every vector file the manifest may reference, embedded at compile time.
19	/// Path keys are manifest-relative (relative to `kat/`).
20	const FIXTURES: &[(&str, &str)] = &[
21	    (
22	        "vectors/codec/accept.json",
23	        include_str!("../kat/vectors/codec/accept.json"),
24	    ),
25	    (
26	        "vectors/codec/reject.json",
27	        include_str!("../kat/vectors/codec/reject.json"),
28	    ),
29	    (
30	        "vectors/codec/unknown_fields.json",
31	        include_str!("../kat/vectors/codec/unknown_fields.json"),
32	    ),
33	];
34	
35	// ---------------------------------------------------------------------------
36	// Manifest + vector file shapes. deny_unknown_fields: a field the schema does
37	// not know is a manifest drift, not a tolerance.
38	// ---------------------------------------------------------------------------
39	
40	#[derive(Deserialize)]
41	#[serde(rename_all = "camelCase", deny_unknown_fields)]
42	struct Manifest {
43	    manifest_version: u64,
44	    profile: String,
45	    codecs: Codecs,
46	    structure_tags: serde_json::Map<String, serde_json::Value>,
47	    kdf_edges: serde_json::Map<String, serde_json::Value>,
48	}
49	
50	#[derive(Deserialize)]
51	#[serde(deny_unknown_fields)]
52	struct Codecs {
53	    #[serde(rename = "det-cbor")]
54	    det_cbor: DetCbor,
55	}
56	
57	#[derive(Deserialize)]
58	#[serde(rename_all = "camelCase", deny_unknown_fields)]
59	struct DetCbor {
60	    accept: AcceptSection,
61	    reject: RejectSection,
62	    unknown_fields: UnknownFieldsSection,
63	}
64	
65	#[derive(Deserialize)]
66	#[serde(rename_all = "camelCase", deny_unknown_fields)]
67	struct AcceptSection {
68	    file: String,
69	    count: usize,
70	    required_kinds: Vec<String>,
71	}
72	
73	#[derive(Deserialize)]
74	#[serde(deny_unknown_fields)]
75	struct RejectSection {
76	    file: String,
77	    count: usize,
78	    checks: Vec<String>,
79	}
80	
81	#[derive(Deserialize)]
82	#[serde(deny_unknown_fields)]
83	struct UnknownFieldsSection {
84	    file: String,
85	    count: usize,
86	}
87	
88	#[derive(Deserialize)]
89	#[serde(deny_unknown_fields)]
90	struct AcceptVector {
91	    name: String,
92	    hex: String,
93	    diag: String,
94	    kinds: Vec<String>,
95	}
96	
97	#[derive(Deserialize)]
98	#[serde(deny_unknown_fields)]
99	struct RejectVector {
100	    name: String,
101	    hex: String,
102	    check: String,
103	    class: String,
104	}
105	
106	#[derive(Deserialize)]
107	#[serde(rename_all = "camelCase", deny_unknown_fields)]
108	struct UnknownVector {
109	    name: String,
110	    hex: String,
111	    known_keys: Vec<String>,
112	    expect_unknown_count: usize,
113	}
114	
115	// ---------------------------------------------------------------------------
116	// Helpers.
117	// ---------------------------------------------------------------------------
118	
119	fn manifest() -> Manifest {
120	    serde_json::from_str(MANIFEST).expect("kat/manifest.json must match the manifest schema")
121	}
122	
123	fn fixture(path: &str) -> &'static str {
124	    FIXTURES
125	        .iter()
126	        .find(|(p, _)| *p == path)
127	        .unwrap_or_else(|| panic!("manifest references {path}, which is not include_str!-embedded"))
128	        .1
129	}
130	
131	fn accept_vectors(m: &Manifest) -> Vec<AcceptVector> {
132	    serde_json::from_str(fixture(&m.codecs.det_cbor.accept.file)).expect("accept.json shape")
133	}
134	
135	fn reject_vectors(m: &Manifest) -> Vec<RejectVector> {
136	    serde_json::from_str(fixture(&m.codecs.det_cbor.reject.file)).expect("reject.json shape")
137	}
138	
139	fn unknown_vectors(m: &Manifest) -> Vec<UnknownVector> {
140	    serde_json::from_str(fixture(&m.codecs.det_cbor.unknown_fields.file))
141	        .expect("unknown_fields.json shape")
142	}
143	
144	fn unhex(name: &str, hex: &str) -> Vec<u8> {
145	    let bytes = hex::decode(hex).unwrap_or_else(|e| panic!("vector {name}: bad hex: {e}"));
146	    // Lowercase hex is part of the fixture contract.
147	    assert_eq!(
148	        hex::encode(&bytes),
149	        hex,
150	        "vector {name}: hex must be lowercase"
151	    );
152	    bytes
153	}
154	
155	// ---------------------------------------------------------------------------
156	// Assertions.
157	// ---------------------------------------------------------------------------
158	
159	#[test]
160	fn manifest_header_is_pinned() {
161	    let m = manifest();
162	    assert_eq!(m.manifest_version, 1);
163	    assert_eq!(m.profile, "cipherbox/v2 det-cbor");
164	}
165	
166	#[test]
167	fn fixture_table_matches_manifest_files() {
168	    let m = manifest();
169	    let referenced = [
170	        m.codecs.det_cbor.accept.file.as_str(),
171	        m.codecs.det_cbor.reject.file.as_str(),
172	        m.codecs.det_cbor.unknown_fields.file.as_str(),
173	    ];
174	    let referenced_set: BTreeSet<&str> = referenced.iter().copied().collect();
175	    assert_eq!(
176	        referenced_set.len(),
177	        referenced.len(),
178	        "manifest must not reference the same file twice"
179	    );
180	    let embedded: BTreeSet<&str> = FIXTURES.iter().map(|(p, _)| *p).collect();
181	    assert_eq!(
182	        referenced_set, embedded,
183	        "manifest files and include_str!-embedded fixtures must match 1:1"
184	    );
185	}
186	
187	#[test]
188	fn vector_counts_are_exact() {
189	    let m = manifest();
190	    assert_eq!(
191	        accept_vectors(&m).len(),
192	        m.codecs.det_cbor.accept.count,
193	        "accept.json count drift"
194	    );
195	    assert_eq!(
196	        reject_vectors(&m).len(),
197	        m.codecs.det_cbor.reject.count,
198	        "reject.json count drift"
199	    );
200	    assert_eq!(
201	        unknown_vectors(&m).len(),
202	        m.codecs.det_cbor.unknown_fields.count,
203	        "unknown_fields.json count drift"
204	    );
205	}
206	
207	#[test]
208	fn vector_names_are_unique_within_each_file() {
209	    let m = manifest();
210	    let mut seen = BTreeSet::new();
211	    for v in accept_vectors(&m) {
212	        assert!(
213	            seen.insert(v.name.clone()),
214	            "duplicate accept vector name {}",
215	            v.name
216	        );
217	    }
218	    seen.clear();
219	    for v in reject_vectors(&m) {
220	        assert!(
221	            seen.insert(v.name.clone()),
222	            "duplicate reject vector name {}",
223	            v.name
224	        );
225	    }
226	    seen.clear();
227	    for v in unknown_vectors(&m) {
228	        assert!(
229	            seen.insert(v.name.clone()),
230	            "duplicate unknown-field vector name {}",
231	            v.name
232	        );
233	    }
234	}
235	
236	#[test]
237	fn reject_checks_list_matches_vectors_and_error_surface() {
238	    let m = manifest();
239	    let listed: BTreeSet<&str> = m
240	        .codecs
241	        .det_cbor
242	        .reject
243	        .checks
244	        .iter()
245	        .map(String::as_str)
246	        .collect();
247	    assert_eq!(
248	        listed.len(),
249	        m.codecs.det_cbor.reject.checks.len(),
250	        "manifest checks list must not contain duplicates"
251	    );
252	
253	    let vectors = reject_vectors(&m);
254	    let in_vectors: BTreeSet<&str> = vectors.iter().map(|v| v.check.as_str()).collect();
255	    assert_eq!(
256	        listed, in_vectors,
257	        "manifest checks must be exactly the distinct checks in reject.json"
258	    );
259	
260	    let all: BTreeSet<&str> = TrustViolation::CHECKS
261	        .iter()
262	        .chain(Malformed::CHECKS)
263	        .copied()
264	        .collect();
265	    assert!(
266	        listed.is_subset(&all),
267	        "every manifest check must exist on the error surface"
268	    );
269	    for check in TrustViolation::CHECKS {
270	        assert!(
271	            listed.contains(check),
272	            "all trust-violation checks are decode-reachable; missing {check}"
273	        );
274	    }
275	
276	    // The only checks without reject vectors are the two that `decode` can
277	    // never emit: unexpected-type (schema-layer accessor failure) and
278	    // unknown-field-collision (encode_map_partial caller bug). Both are
279	    // unit-test-pinned in src/codec/fields.rs.
280	    let absent: BTreeSet<&str> = all.difference(&listed).copied().collect();
281	    let expected_absent: BTreeSet<&str> = ["unexpected-type", "unknown-field-collision"]
282	        .into_iter()
283	        .collect();
284	    assert_eq!(
285	        absent, expected_absent,
286	        "reject vectors must cover every decode-reachable check"
287	    );
288	}
289	
290	#[test]
291	fn accept_kinds_cover_required_kinds_exactly() {
292	    let m = manifest();
293	    let required: BTreeSet<&str> = m
294	        .codecs
295	        .det_cbor
296	        .accept
297	        .required_kinds
298	        .iter()
299	        .map(String::as_str)
300	        .collect();
301	    assert_eq!(
302	        required.len(),
303	        m.codecs.det_cbor.accept.required_kinds.len(),
304	        "requiredKinds must not contain duplicates"
305	    );
306	
307	    let vectors = accept_vectors(&m);
308	    for kind in &required {
309	        assert!(
310	            vectors.iter().any(|v| v.kinds.iter().any(|k| k == kind)),
311	            "required kind {kind} has no accept vector"
312	        );
313	    }
314	    for v in &vectors {
315	        assert!(!v.kinds.is_empty(), "accept vector {} has no kinds", v.name);
316	        for k in &v.kinds {
317	            assert!(
318	                required.contains(k.as_str()),
319	                "accept vector {} has kind {k} outside requiredKinds",
320	                v.name
321	            );
322	        }
323	    }
324	}
325	
326	#[test]
327	fn accept_vectors_decode_reencode_and_render_diag() {
328	    let m = manifest();
329	    for v in accept_vectors(&m) {
330	        let bytes = unhex(&v.name, &v.hex);
331	        let value = decode(&bytes)
332	            .unwrap_or_else(|e| panic!("accept vector {}: decoder rejected it: {e}", v.name));
333	        assert_eq!(
334	            hex::encode(encode(&value)),
335	            v.hex,
336	            "accept vector {}: re-encode must be byte-identical",
337	            v.name
338	        );
339	        assert_eq!(
340	            value.to_string(),
341	            v.diag,
342	            "accept vector {}: diagnostic-notation drift",
343	            v.name
344	        );
345	    }
346	}
347	
348	#[test]
349	fn reject_vectors_fire_the_named_check() {
350	    let m = manifest();
351	    for v in reject_vectors(&m) {
352	        let bytes = unhex(&v.name, &v.hex);
353	        let err = match decode(&bytes) {
354	            Err(e) => e,
