    debug_assert!(
        depth < super::MAX_DEPTH,
        "Value nesting exceeds MAX_DEPTH; the encoding would be undecodable"
    );
    match value {
        Value::Unsigned(n) => write_head(out, MAJOR_UNSIGNED, *n),
        Value::Negative(n) => write_head(out, MAJOR_NEGATIVE, *n),
        Value::Bytes(b) => {
