32	use crate::suite::aead::{self, KEY_LEN, NONCE_LEN, TAG_LEN};
33	
34	/// Seal `plaintext` under `key`/`nonce` with the structured AAD for `ctx`.
35	/// Returns the wire sealed blob `nonce(24) || ciphertext||tag`.
36	///
37	/// `nonce` **must be unique for every seal performed with a given `key`**:
38	/// XChaCha20-Poly1305 nonce reuse under one key is a confidentiality and
39	/// integrity break. It is caller-injected entropy (KATs pin it; production
40	/// callers source it from their injected entropy seam), prefixed so [`unseal`]
41	/// can recover it, and authenticated by the AEAD rather than by the AAD
42	/// (#39 D7). The caller owns `plaintext` and is its terminal owner for
43	/// zeroization (a callee never zeroizes a caller-owned buffer).
44	pub fn seal(
45	    key: &[u8; KEY_LEN],
46	    nonce: &[u8; NONCE_LEN],
47	    ctx: &AadContext,
48	    plaintext: &[u8],
49	) -> Vec<u8> {
50	    let aad = build_aad(ctx);
51	    let mut out = Vec::with_capacity(NONCE_LEN + plaintext.len() + TAG_LEN);
52	    out.extend_from_slice(nonce);
53	    out.extend(aead::encrypt(key, nonce, &aad, plaintext));
54	    out
55	}
56	
57	/// Open a wire sealed blob (`nonce(24) || ciphertext||tag`) under `key` and the
58	/// structured AAD for `ctx`. Returns the recovered plaintext (the caller's to
59	/// own and zeroize).
60	///
61	/// Fail-closed, two-class: a blob too short to hold the nonce and tag is
62	/// [`Malformed::Truncated`]; a tag that does not verify — tampering, an AAD
63	/// transplant, or a `v` downgrade — is [`TrustViolation::SealOpenFailed`], never
64	/// a silent degrade.
65	pub fn unseal(key: &[u8; KEY_LEN], ctx: &AadContext, sealed: &[u8]) -> Result<Vec<u8>, CodecError> {
66	    if sealed.len() < NONCE_LEN + TAG_LEN {
67	        return Err(Malformed::Truncated {
68	            offset: sealed.len(),
69	        }
70	        .into());
71	    }
72	    let (nonce, ciphertext) = sealed.split_at(NONCE_LEN);
73	    let nonce: &[u8; NONCE_LEN] = nonce.try_into().expect("split_at NONCE_LEN");
74	    let aad = build_aad(ctx);
75	    aead::decrypt(key, nonce, &aad, ciphertext).ok_or_else(|| TrustViolation::SealOpenFailed.into())
76	}
