96	        let sealed = seal(&key, &nonce, &ctx(), b"hello body");
97	        assert_eq!(&sealed[..NONCE_LEN], &nonce, "nonce is prefixed");
98	        assert_eq!(unseal(&key, &ctx(), &sealed).unwrap(), b"hello body");
99	    }
