103	        let key = [5u8; KEY_LEN];
104	        let nonce = [6u8; NONCE_LEN];
105	        let sealed = seal(&key, &nonce, &ctx(), b"hello body");
106	        // Unseal computing the AAD from a different struct tag: the tag fails.
107	        let mut wrong = ctx();
108	        wrong.struct_tag = STRUCT_TAG_WRITE_BODY;
109	        assert_eq!(
110	            unseal(&key, &wrong, &sealed).unwrap_err().check(),
111	            "seal-open-failed"
