117	        let key = [5u8; KEY_LEN];
118	        // Below the nonce+tag floor: structurally too short.
119	        let short = vec![0u8; NONCE_LEN + TAG_LEN - 1];
120	        assert_eq!(
121	            unseal(&key, &ctx(), &short).unwrap_err().check(),
122	            "truncated"
123	        );
124	    }
