1	//! The content-DAG CID codec (blueprint/core.md "Open edges"; AGENTS.md rules
2	//! 4-5: content-address codecs live in core, one KAT set).
3	//!
4	//! The deterministic CIDv1 content address of a sealed content blob, computed
5	//! beside the in-core name codec ([`crate::ipns::name`], which likewise
6	//! hand-assembles a fixed CIDv1 byte prefix). The digest is the frozen suite
7	//! hash BLAKE3-256 ([`crate::suite::hash::hash`]) — no content hash lives
8	//! outside the suite (AGENTS.md rule 4) — so the CID is byte-identical on native
9	//! and wasm32.
10	//!
11	//! CIDv1 layout — all four framing bytes are single-byte multicodec varints, so
12	//! the CID is a fixed 4-byte prefix followed by the digest:
13	//!
14	//! | byte   | meaning                                                    |
15	//! | ------ | ---------------------------------------------------------- |
16	//! | `0x01` | CID version 1                                              |
17	//! | `0x55` | multicodec `raw` — core addresses the opaque sealed bytes  |
18	//! | `0x1e` | multihash `blake3` (the frozen suite hash)                 |
19	//! | `0x20` | multihash digest length = 32                               |
20	//! | …      | 32-byte BLAKE3 digest of the sealed bytes                  |
21	//!
22	//! `raw` (0x55) is the spec-faithful codec: the DAG assembly shape is
23	//! engine-owned (#630), so core sees an opaque sealed byte string — not a DAG it
24	//! can interpret — and addresses those bytes as raw leaf content. If #630 needs
25	//! intermediate DAG nodes under a structured codec, that is the engine's concern
26	//! above this primitive.
27	
28	use crate::error::{CodecError, TrustViolation};
29	use crate::suite::hash::hash;
30	use crate::suite::secret::SECRET_LEN;
31	
32	/// CIDv1 multicodec for the content plane: `raw` (0x55). See the module docs for
33	/// why raw is the spec-faithful choice over a DAG codec here.
34	pub const CONTENT_CID_CODEC: u8 = 0x55;
35	
36	/// Multihash code for BLAKE3-256 (0x1e) — the frozen suite hash
37	/// ([`crate::suite::hash::hash`]).
38	pub const CONTENT_CID_MULTIHASH: u8 = 0x1e;
39	
40	/// The multihash digest width: the suite BLAKE3 hash output, `SECRET_LEN`
41	/// (32 bytes). Tied to the suite so a hash-width change is a compile-time break.
42	const DIGEST_LEN: usize = SECRET_LEN;
43	
44	/// The fixed CIDv1 byte prefix that precedes the digest.
45	const CID_PREFIX: [u8; 4] = [
46	    0x01,
47	    CONTENT_CID_CODEC,
48	    CONTENT_CID_MULTIHASH,
49	    DIGEST_LEN as u8,
50	];
51	
52	/// Total CIDv1 byte length: the 4-byte prefix plus the 32-byte digest.
53	pub const CONTENT_CID_LEN: usize = CID_PREFIX.len() + DIGEST_LEN;
54	
55	/// Compute the content CID (binary CIDv1) of `sealed` — the exact opaque bytes
56	/// stored on IPFS (`nonce || ciphertext||tag`). Deterministic and byte-identical
57	/// across native and wasm32; a public content address, so no key material flows
58	/// through here.
59	pub fn compute_cid(sealed: &[u8]) -> Vec<u8> {
60	    let digest = hash(sealed);
61	    let mut cid = Vec::with_capacity(CONTENT_CID_LEN);
62	    cid.extend_from_slice(&CID_PREFIX);
63	    cid.extend_from_slice(&digest);
64	    cid
65	}
66	
67	/// Verify that `sealed` content-addresses to `claimed_cid`, fail-closed. Any
68	/// mismatch — tampered bytes or a wrong claimed CID — is
69	/// [`TrustViolation::ContentCidMismatch`], never mere staleness. The comparison
70	/// is over a public content address (no secret), so ordinary equality is used.
71	pub fn verify_cid(claimed_cid: &[u8], sealed: &[u8]) -> Result<(), CodecError> {
72	    if compute_cid(sealed) == claimed_cid {
73	        Ok(())
74	    } else {
75	        Err(TrustViolation::ContentCidMismatch.into())
76	    }
77	}
78	
